    fun forSelector(selector: Int): List<DelphiParameterDescriptor> =
        all.filter { it.selector == selector }.sortedBy { it.id }

    fun find(selector: Int, id: Int): DelphiParameterDescriptor? =
        all.firstOrNull { it.selector == selector && it.id == id }

    fun readModeLabel(mode: Int): String = when (mode) {
        0 -> "U16 little-endian"
        1 -> "byte"
        2 -> "U16 big-endian"
        3 -> "calculado"
        else -> "desconocido"
    }
}
